  "claims": [
    {
      "claim": "Gabapentin, a small polar primary amine, has about 60% absolute oral bioavailability in humans and 98.2% fraction absorbed after oral solution in rats, supporting that small primary amines can reach F at or above 20%.",
      "card_ids": ["C05", "C52"]
    },
    {
      "claim": "Ciclacillin, a beta-lactam bearing a primary aminocyclohexane side chain, is reported to have high oral availability, supporting high F for a rigid primary amine.",
      "card_ids": ["C14"]
    },
    {
      "claim": "An adamantylamine-containing compound showed no significant P-gp-mediated efflux in Caco-2 with elacridar, reducing presystemic efflux concern for the adamantane amine motif.",
      "card_ids": ["C56"]
    },
    {
      "claim": "An adamantylamine-containing oxazole compound showed low intrinsic clearance in human liver microsomes, providing weak mechanistic support that the adamantylamine motif is not rapidly cleared.",
      "card_ids": ["C70"]
    },
    {
      "claim": "High intrinsic clearance records in L6 involve aniline amide or anilide scaffolds rather than the query primary aliphatic amine, so they have low transferability and do not affirmatively support F below 20%.",
      "card_ids": ["C67", "C74", "C77"]
    },
    {
      "claim": "Gentamicin has negligible or zero oral bioavailability, but as a large hydrophilic polycationic aminoglycoside it has low transferability to the small rigid monoamine query.",
      "card_ids": ["C22", "C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C70", "C67", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct amantadine-specific oral bioavailability record is present; prediction is transfer-based.",
    "No IV-reference AUC or absolute F measurement for the query molecule is supplied.",
    "No formulation, prandial state, or dose information for the query is supplied.",
    "The closest analogue absorption evidence, gabapentin fraction absorbed, is from rats rather than humans.",
    "The query is fully ionized at pH 7.4 with low logD, leaving passive permeability uncertain despite small size and low TPSA.",
    "L6 hepatic clearance records mostly involve other chemotypes; no human hepatic extraction or metabolic stability measurement exists for the query itself."
  ],
  "decision_summary": "Predicted high because transferable direct F records for small polar oral drugs and close structural analogues (gabapentin about 60% human F and 98% rat fraction absorbed; ciclacillin high oral availability) support F at or above 20%, and L5 showed an adamantylamine-containing compound is not an intestinal P-gp substrate. L6 adds no affirmative low-F evidence: the only adamantylamine-containing metabolic record shows low human microsomal clearance, while high-clearance records involve amide or aniline scaffolds with low transferability. Confidence remains moderate because no direct amantadine F measurement is available."
}

